Program sort3;

Var
{}i,j,n,r:integer;
{}a:array[1..1000]of byte;
{}t:array[1..3]of integer;

Begin
{}Assign(input, ‘sort3.in’); Reset(input);
{}Assign(output,  ‘sort3.out’); Rewrite(output);

{}fillchar(t,sizeof(t),0);
{}r:=0;

{}readln(n);
{}for i:=1 to n do begin
{}{}readln(a[i]);
{}{}inc(t[a[i]])
{}end; {输入与统计}

{}j:=t[1];
{}for i:=1 to t[1]do
{}{}if a[i]=2 then begin
{}{}{}inc(r);
{}{}{}repeat
{}{}{}{}inc(j);
{}{}{}until a[j]=1;
{}{}{}a[i]:=1;
{}{}{}a[j]:=2;
{}{}end; {交换1和2}

{}for i:=1 to t[1]do
{}{}if a[i]=3 then begin
{}{}{}inc(r);
{}{}{}a[i]:=1;
{}{}end;
{}for i:=t[1]+1 to n do
{}{}if a[i]=1then
{}{}{}a[i]:=3; {交换1和3}

{}for i:=t[1]+1 to t[1]+t[2]do
{}{}if a[i]=3 then
{}{}{}inc(r); {统计交换2和3所需次数}

{}writeln(r);

{}Close(input);
{}Close(output);
End.

